ALTER TABLE gentum_user ADD COLUMN password_salt TEXT, ADD COLUMN password_hash TEXT;
CREATE TABLE user_session (token_hash TEXT PRIMARY KEY, user_id UUID NOT NULL REFERENCES gentum_user(id), expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX user_session_expiry ON user_session(expires_at);
ALTER TABLE account ADD CONSTRAINT account_owner_key UNIQUE(user_id,id);
CREATE TABLE category (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES gentum_user(id), name VARCHAR(100) NOT NULL CHECK(btrim(name)<>''), kind TEXT NOT NULL CHECK(kind IN ('INCOME','EXPENSE')), UNIQUE(user_id,id), UNIQUE(user_id,name,kind));
CREATE TABLE recurring (id UUID PRIMARY KEY, user_id UUID NOT NULL, account_id UUID NOT NULL, category_id UUID NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('INCOME','EXPENSE')), amount BIGINT NOT NULL CHECK(amount>0), description VARCHAR(200) NOT NULL, next_date DATE NOT NULL, anchor_day INT NOT NULL CHECK(anchor_day BETWEEN 1 AND 31), active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(user_id,account_id) REFERENCES account(user_id,id), FOREIGN KEY(user_id,category_id) REFERENCES category(user_id,id), UNIQUE(user_id,id));
CREATE TABLE entry (id UUID PRIMARY KEY, user_id UUID NOT NULL, account_id UUID NOT NULL, category_id UUID, kind TEXT NOT NULL CHECK(kind IN ('INCOME','EXPENSE','TRANSFER_IN','TRANSFER_OUT')), amount BIGINT NOT NULL CHECK(amount>0), description VARCHAR(200) NOT NULL, entry_date DATE NOT NULL, transfer_id UUID, recurring_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(user_id,account_id) REFERENCES account(user_id,id), FOREIGN KEY(user_id,category_id) REFERENCES category(user_id,id), FOREIGN KEY(user_id,recurring_id) REFERENCES recurring(user_id,id), UNIQUE(recurring_id,entry_date), CHECK((kind IN ('TRANSFER_IN','TRANSFER_OUT')) = (transfer_id IS NOT NULL)), CHECK((kind IN ('INCOME','EXPENSE')) = (category_id IS NOT NULL)));
CREATE INDEX entry_owner_date ON entry(user_id,entry_date,id);
CREATE TABLE budget (id UUID PRIMARY KEY, user_id UUID NOT NULL, category_id UUID NOT NULL, currency CHAR(3) NOT NULL CHECK(currency IN ('EUR','GBP','USD','BRL')), month DATE NOT NULL CHECK(EXTRACT(DAY FROM month)=1), amount BIGINT NOT NULL CHECK(amount>0), FOREIGN KEY(user_id,category_id) REFERENCES category(user_id,id), UNIQUE(user_id,category_id,currency,month));
